// Extraire la traduction intermédiaire (anglais)
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Vérifier les erreurs
const hasError = statusCode >= 400 || data.type === 'error' || (data.error && data.error.message);
if (hasError) {
  const errorMsg = data.error?.message || data.message || `Erreur HTTP ${statusCode}`;
  return [{
    json: {
      success: false,
      requestId: prevData.requestId,
      error: {
        code: statusCode >= 400 ? statusCode : 500,
        message: `Erreur Step 1 (Claude): ${errorMsg}`,
        status: 'PIVOT_STEP1_ERROR'
      }
    }
  }];
}

// Extraire la traduction anglaise
let englishTranslation = '';
if (data.content && data.content[0] && data.content[0].text) {
  englishTranslation = data.content[0].text.trim();
}

if (!englishTranslation) {
  return [{
    json: {
      success: false,
      requestId: prevData.requestId,
      error: {
        code: 500,
        message: 'Aucune traduction intermédiaire retournée',
        status: 'EMPTY_INTERMEDIATE_RESPONSE'
      }
    }
  }];
}

// Préparer pour Step 2
return [{
  json: {
    intermediateTranslation: englishTranslation,
    originalText: prevData.text,
    sourceLanguage: prevData.sourceLanguage,
    sourceLangName: prevData.sourceLangName,
    targetLanguage: prevData.targetLanguage,
