// Extraire la traduction directe (sans pivot)
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Vérifier les erreurs
const hasError = statusCode >= 400 || data.type === 'error' || (data.error && data.error.message);
if (hasError) {
  const errorMsg = data.error?.message || data.message || `Erreur HTTP ${statusCode}`;
  return [{
    json: {
      success: false,
      requestId: prevData.requestId,
      error: {
        code: statusCode >= 400 ? statusCode : 500,
        message: `Erreur Claude Direct: ${errorMsg}`,
        status: 'DIRECT_TRANSLATION_ERROR'
      }
    }
  }];
}

// Extraire la traduction
let claudeTranslation = '';
if (data.content && data.content[0] && data.content[0].text) {
  claudeTranslation = data.content[0].text.trim();
}

if (!claudeTranslation) {
  return [{
    json: {
      success: false,
      requestId: prevData.requestId,
      error: {
        code: 500,
        message: 'Aucune traduction retournée',
        status: 'EMPTY_DIRECT_RESPONSE'
      }
    }
  }];
}

// Préparer pour vérification GPT
return [{
  json: {
    claudeTranslation: claudeTranslation,
    intermediateTranslation: null,
    originalText: prevData.text,
    sourceLanguage: prevData.sourceLanguage,
    sourceLangName: prevData.sourceLangName,
    targetLanguage: prevData.targetLanguage,
    targetLangName: prevData.targetLangName,
    contextInfo: prevData.contextInfo,
    context: prevData.context,
    openaiApiKey: prevData.openaiApiKey,
    discord: prevData.discord,
    requestId: prevData.requestId,
    startTime: prevData.startTime,
    mode: prevData.mode,
    claudeModel: prevData.claudeModel,
    openaiModel: prevData.openaiModel,
    pivotUsed: false,
    llmUsage: [
      {
        model: prevData.claudeModel,
        provider: 'anthropic',
        step: 'direct_translation',
        input_tokens: data.usage?.input_tokens || 0,
        output_tokens: data.usage?.output_tokens || 0,
        total_tokens: (data.usage?.input_tokens || 0) + (data.usage?.output_tokens || 0)
      }
    ]
  }
}];

// Formater la réponse finale
const gptResponse = $input.first().json;
const translationData = $('Merge Translations').first().json;

const endTime = Date.now();
const processingTime = endTime - translationData.startTime;

// Récupérer les modèles utilisés
const claudeModel = translationData.claudeModel || 'claude-sonnet-4-20250514';
const openaiModel = translationData.openaiModel || 'gpt-4o';
const mode = translationData.mode || 'standard';
const pivotUsed = translationData.pivotUsed || false;

// Parser la réponse OpenAI
const gptData = gptResponse.body || gptResponse;
const gptStatusCode = gptResponse.statusCode || 200;

// Valeurs par défaut si OpenAI échoue
let verification = {
  my_translation: null,
  approved: true,
  confidence: 0.7,
  issues: [],
  notes: 'Vérification OpenAI non disponible'
};

let gptUsageRaw = { prompt_tokens: 0, completion_tokens: 0 };
let verifierError = null;

if (gptStatusCode >= 400 || gptData.error) {
  verifierError = gptData.error?.message || gptData.error?.code || `HTTP ${gptStatusCode}`;
} else if (gptData.choices && gptData.choices[0]?.message?.content) {
  try {
    verification = JSON.parse(gptData.choices[0].message.content);
    gptUsageRaw = gptData.usage || gptUsageRaw;
  } catch (e) {
    verifierError = 'Erreur parsing JSON: ' + e.message;
  }
} else {
  verifierError = 'Réponse OpenAI invalide';
}

// Les traductions
const claudeTranslation = translationData.claudeTranslation;
const gptTranslation = verification.my_translation || null;
const intermediateTranslation = translationData.intermediateTranslation || null;

// Logique de validation: verification.approved === true
const confidence = verification.confidence || 0.7;
const isAutoApproved = verification.approved === true;
const status = isAutoApproved ? 'approved' : 'draft';

// Construire llm_usage
const llmUsage = [
  ...translationData.llmUsage,
  {
    model: openaiModel,
    provider: 'openai',
    step: 'verification',
    input_tokens: gptUsageRaw.prompt_tokens || 0,
    output_tokens: gptUsageRaw.completion_tokens || 0,
    total_tokens: (gptUsageRaw.prompt_tokens || 0) + (gptUsageRaw.completion_tokens || 0)
  }
];

const totalTokens = llmUsage.reduce((sum, u) => sum + (u.total_tokens || 0), 0);

// Construire les traductions par code langue
// Si pivot: translation_en (intermédiaire) + translation_{target}
// Si direct vers EN: translation_en uniquement
// Si direct depuis EN: translation_{target} uniquement
const sourceLanguage = translationData.sourceLanguage;
const targetLanguage = translationData.targetLanguage;

const translationsByLang = {};
if (pivotUsed) {
  // Pivot: he -> en -> fr
  translationsByLang['translation_en'] = intermediateTranslation;
  translationsByLang['translation_' + targetLanguage] = claudeTranslation;
} else if (targetLanguage === 'en') {
  // Direct vers EN: he -> en
  translationsByLang['translation_en'] = claudeTranslation;
} else {
  // Direct depuis EN: en -> fr
  translationsByLang['translation_' + targetLanguage] = claudeTranslation;
}

// Construire la réponse
const response = {
  success: true,
  requestId: translationData.requestId,
  status: status,
  mode: mode,
  pivot_used: pivotUsed,
  translation: {
    original: translationData.originalText,
    intermediate: intermediateTranslation,
    claude: claudeTranslation,
    openai: gptTranslation,
    final: isAutoApproved ? claudeTranslation : null,
    source_language: sourceLanguage,
    target_language: targetLanguage
  },
  verification: {
    approved: verification.approved,
    confidence: confidence,
    auto_approved: isAutoApproved,
    issues: verification.issues || [],
    notes: verification.notes || null,
    verifier_error: verifierError
  },
  metadata: {
    traite: translationData.context.traite || null,
    page: translationData.context.page || null,
    commentator: translationData.context.commentator || null,
    models_used: [claudeModel, openaiModel],
    mode: mode,
    pivot_used: pivotUsed,
    source: 'generated',
    processing_time_ms: processingTime
  },
  llm_usage: llmUsage,
  total_tokens: totalTokens,
  discord: translationData.discord,
  // Données pour sauvegarde
  _saveData: {
    text: translationData.originalText,
    translated_text: isAutoApproved ? claudeTranslation : null,
    ...translationsByLang,
    claude_translation: claudeTranslation,
    gpt_translation: gptTranslation,
    status: status,
    source_language: sourceLanguage,
    target_language: targetLanguage,
    traite: translationData.context.traite || null,
    page: translationData.context.page || null,
    commentator: translationData.context.commentator || null,
    quality_score: confidence,
    notes: verification.notes || null,
    issues: verification.issues || [],
    provider: 'claude+openai',
    model: claudeModel + '+' + openaiModel,
    mode: mode,
    pivot_used: pivotUsed,
    request_id: translationData.requestId,
    llm_usage: llmUsage
  }
};

return [{ json: response }];

// Nettoyer la réponse (supprimer _saveData)
const input = $input.first().json;
const prevResponse = $('Format Final Response').first().json;

// Supprimer les données internes
const response = { ...prevResponse };
delete response._saveData;

return [{ json: response }];

